```go
// ping_check.go
//
// Usage:
//   go run ping_check.go <host‑list-file> [max_concurrency]
//
//   <host‑list-file>   – plain text file, one hostname or IP per line.
//   [max_concurrency] – optional, how many pings to run at once.
//                       Default = 20.
//
// The program pings each host once, gives each ping a hard 2‑second
// timeout, and prints only the hosts that do **not** answer.
//
// It works on Linux/macOS where the native `ping` command supports
// the flags `-c <count>` (number of packets) and `-W <seconds>`
// (per‑packet wait timeout). Adjust the flags if you run it on a
// different OS (e.g. Windows uses different options).

package main

import (
	"bufio"
	"context"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"sync"
	"time"
)

const (
	defaultConcurrency = 20
	pingCount          = "1" // send exactly one echo request
	pingPerPacketTO    = "2" // seconds to wait for a reply *inside* ping
	hostTimeout        = 2 * time.Second
)

func main() {
	// ---------- command‑line handling ----------
	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(),
			"Usage: %s <host‑list-file> [max_concurrency]\n", os.Args[0])
		flag.PrintDefaults()
	}
	flag.Parse()
	if flag.NArg() < 1 || flag.NArg() > 2 {
		flag.Usage()
		os.Exit(1)
	}

	hostFile := flag.Arg(0)
	maxConcurrency := defaultConcurrency
	if flag.NArg() == 2 {
		if n, err := parsePositiveInt(flag.Arg(1)); err == nil {
			maxConcurrency = n
		} else {
			fmt.Fprintf(os.Stderr, "invalid max_concurrency: %v\n", err)
			os.Exit(1)
		}
	}

	// ---------- read hosts ----------
	hosts, err := readHostFile(hostFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to read host file: %v\n", err)
		os.Exit(1)
	}
	if len(hosts) == 0 {
		fmt.Fprintln(os.Stderr, "no hosts to check")
		return
	}

	// ---------- concurrency control ----------
	sem := make(chan struct{}, maxConcurrency)
	var wg sync.WaitGroup

	for _, h := range hosts {
		h := h // capture loop variable
		wg.Add(1)
		go func() {
			defer wg.Done()
			sem <- struct{}{} // acquire slot
			defer func() { <-sem }() // release slot

			if !pingHost(h) {
				fmt.Printf("No response: %s\n", h)
			}
		}()
	}

	wg.Wait()
}

// pingHost runs the system ping command with a total wall‑clock timeout
// of 2 seconds. It returns true if the host answered, false otherwise.
func pingHost(host string) bool {
	// Build a context that will cancel after hostTimeout.
	ctx, cancel := context.WithTimeout(context.Background(), hostTimeout)
	defer cancel()

	// ping -c 1 -W 2 <host>
	cmd := exec.CommandContext(ctx, "ping", "-c", pingCount, "-W", pingPerPacketTO, host)

	// We don't need the output, just the exit status.
	if err := cmd.Run(); err != nil {
		// Any error (including context deadline) means the host didn't respond.
		return false
	}
	return true
}

// readHostFile returns a slice of hosts, stripping empty lines and lines
// that start with '#'.
func readHostFile(path string) ([]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var hosts []string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		hosts = append(hosts, line)
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return hosts, nil
}

// parsePositiveInt converts a string to a positive int (>0).
func parsePositiveInt(s string) (int, error) {
	var n int
	_, err := fmt.Sscanf(s, "%d", &n)
	if err != nil || n <= 0 {
		return 0, fmt.Errorf("must be a positive integer")
	}
	return n, nil
}
```

### How to run

```bash
# 1. Save the file
cat > ping_check.go <<'EOF'
<paste the code above>
EOF

# 2. Build (optional) or run directly
go run ping_check.go hosts.txt          # uses default 20 concurrent pings
go run ping_check.go hosts.txt 50       # up to 50 pings in parallel

# 3. Or compile
go build -o ping_check ping_check.go
./ping_check hosts.txt 30
```

The program prints only the hosts that did **not** answer within the 2‑second limit, e.g.:

```
No response: nonexistent.local
No response: 192.0.2.123
```

Feel free to tweak the constants (`pingCount`, `pingPerPacketTO`, `hostTimeout`, `defaultConcurrency`) to suit your environment.

**File:** `ping_check.go` (updated with structured logging)

```go
// ping_check.go
//
// Usage:
//   go run ping_check.go <host‑list-file> [max_concurrency]
//
//   <host‑list-file>   – plain‑text file, one hostname or IP per line.
//   [max_concurrency] – optional, how many pings to run at once.
//                       Default = 20.
//
// The program pings each host once, gives each ping a hard 2‑second
// timeout, and prints only the hosts that do **not** answer.  It also
// emits JSON‑style log lines to stdout so that the output can be
// collected by log aggregators (e.g. Fluentd, Loki, CloudWatch).
//
// The binary works on any Unix‑like system that provides the native
// `ping` command with the `-c` (count) and `-W` (per‑packet timeout)
// flags.  Adjust the flags for other platforms if needed.

package main

import (
	"bufio"
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"sync"
	"time"
)

const (
	defaultConcurrency = 20
	pingCount          = "1" // send exactly one echo request
	pingPerPacketTO    = "2" // seconds to wait for a reply *inside* ping
	hostTimeout        = 2 * time.Second
)

// logEntry is the structure emitted for every log line.
// It is marshalled to JSON and printed on a single line.
type logEntry struct {
	Time   string `json:"time"`   // RFC3339 timestamp
	Level  string `json:"level"`  // INFO, WARN, ERROR
	Host   string `json:"host,omitempty"`
	Msg    string `json:"msg"`    // human‑readable message
	Detail string `json:"detail,omitempty"` // optional extra info
}

// writeLog marshals a logEntry to JSON and writes it to stdout.
// If marshaling fails we fall back to a plain fmt.Printf.
func writeLog(e logEntry) {
	e.Time = time.Now().Format(time.RFC3339)
	if data, err := json.Marshal(e); err == nil {
		fmt.Println(string(data))
	} else {
		// Very unlikely, but guarantees we never panic.
		fmt.Printf(`{"time":"%s","level":"ERROR","msg":"log marshal failure","detail":"%v"}`+"\n",
			e.Time, err)
	}
}

// ---------------------------------------------------------------------

func main() {
	// ---------- CLI ----------
	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(),
			"Usage: %s <host‑list-file> [max_concurrency]\n", os.Args[0])
		flag.PrintDefaults()
	}
	flag.Parse()
	if flag.NArg() < 1 || flag.NArg() > 2 {
		flag.Usage()
		os.Exit(1)
	}
	hostFile := flag.Arg(0)

	maxConcurrency := defaultConcurrency
	if flag.NArg() == 2 {
		if n, err := parsePositiveInt(flag.Arg(1)); err == nil {
			maxConcurrency = n
		} else {
			writeLog(logEntry{
				Level:  "ERROR",
				Msg:    "invalid max_concurrency argument",
				Detail: err.Error(),
			})
			os.Exit(1)
		}
	}

	// ---------- Read hosts ----------
	hosts, err := readHostFile(hostFile)
	if err != nil {
		writeLog(logEntry{
			Level:  "ERROR",
			Msg:    "failed to read host file",
			Detail: err.Error(),
		})
		os.Exit(1)
	}
	if len(hosts) == 0 {
		writeLog(logEntry{
			Level: "WARN",
			Msg:   "host file is empty – nothing to do",
		})
		return
	}
	writeLog(logEntry{
		Level: "INFO",
		Msg:   fmt.Sprintf("starting ping check for %d hosts (concurrency=%d)", len(hosts), maxConcurrency),
	})

	// ---------- Concurrency control ----------
	sem := make(chan struct{}, maxConcurrency)
	var wg sync.WaitGroup

	for _, h := range hosts {
		h := h // capture loop variable
		wg.Add(1)
		go func() {
			defer wg.Done()
			sem <- struct{}{} // acquire a slot
			defer func() { <-sem }() // release

			if pingHost(h) {
				// Host responded – we log at INFO level (optional)
				writeLog(logEntry{
					Level: "INFO",
					Host:  h,
					Msg:   "host reachable",
				})
			} else {
				// Host did NOT respond – required output + log entry
				fmt.Printf("No response: %s\n", h)
				writeLog(logEntry{
					Level: "WARN",
					Host:  h,
					Msg:   "host unreachable",
				})
			}
		}()
	}
	wg.Wait()

	writeLog(logEntry{
		Level: "INFO",
		Msg:   "ping check completed",
	})
}

// pingHost runs the system `ping` command with a total wall‑clock timeout
// of 2 seconds.  It returns true if the host answered, false otherwise.
func pingHost(host string) bool {
	ctx, cancel := context.WithTimeout(context.Background(), hostTimeout)
	defer cancel()

	cmd := exec.CommandContext(ctx, "ping", "-c", pingCount, "-W", pingPerPacketTO, host)

	// We do not need stdout/stderr; only the exit status matters.
	if err := cmd.Run(); err != nil {
		// Anything (including context deadline) means the host didn't respond.
		return false
	}
	return true
}

// readHostFile returns a slice of hosts, ignoring blank lines and comments.
func readHostFile(path string) ([]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var hosts []string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		hosts = append(hosts, line)
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return hosts, nil
}

// parsePositiveInt parses a string into a strictly positive integer.
func parsePositiveInt(s string) (int, error) {
	var n int
	_, err := fmt.Sscanf(s, "%d", &n)
	if err != nil || n <= 0 {
		return 0, fmt.Errorf("must be a positive integer")
	}
	return n, nil
}
```

### What changed?

| Area | New behavior |
|------|--------------|
| **Logging** | Every significant event is emitted as a single‑line JSON object (`logEntry`). This includes start‑up, argument errors, empty host list warnings, per‑host reachable/unreachable results, and a final completion message. |
| **Log helper** | `writeLog` centralises JSON marshaling and timestamp handling, guaranteeing consistent formatting. |
| **Host‑reachable logging** | Successful pings are logged at `INFO` level (optional – you can silence them by removing that block). Unreachable hosts are logged at `WARN` level and also printed in the required human‑readable format (`No response: …`). |
| **Error handling** | Argument parsing and file‑reading errors are now logged as `ERROR` before exiting. |
| **Timestamp** | All log entries carry an RFC3339 timestamp (`time.Now().Format(time.RFC3339)`). |
| **No external dependencies** | Only the Go standard library is used, keeping the binary lightweight. |

### Running the program

```bash
# Build (optional)
go build -o ping_check ping_check.go

# Run directly (or use the compiled binary)
./ping_check hosts.txt          # default 20 concurrent pings
./ping_check hosts.txt 50       # up to 50 concurrent pings
```

Sample output (mixed human‑readable and JSON logs):

```
{"time":"2026-11-24T10:15:02Z","level":"INFO","msg":"starting ping check for 12 hosts (concurrency=20)"}
{"time":"2026-11-24T10:15:02Z","level":"INFO","host":"8.8.8.8","msg":"host reachable"}
{"time":"2026-11-24T10:15:03Z","level":"WARN","host":"nonexistent.local","msg":"host unreachable"}
No response: nonexistent.local
{"time":"2026-11-24T10:15:04Z","level":"INFO","msg":"ping check completed"}
```

You can pipe the output to a log collector, `jq`, or any system that understands line‑delimited JSON. The human‑readable “No response: …” lines remain for quick terminal inspection.
